const listWorkspaceActivityOptimized = `-- name: ListWorkspaceActivityOptimized :many
SELECT
    al.id,
    al.type,
    al.description,
    al.entity_type,
    al.entity_id,
    al.created_at,
    u.id AS user_id,
    u.first_name,
    u.last_name,
    u.email,
    u.avatar,
    COALESCE(t.slug, ct.slug)::text AS task_slug,
    COALESCE(tp.slug, ctp.slug)::text AS task_project_slug,
    COALESCE(tw.slug, ctw.slug)::text AS task_workspace_slug,
    pp.slug::text AS project_slug,
    pw.slug::text AS project_workspace_slug,
    ws.slug::text AS workspace_slug,
    sp.slug::text AS sprint_slug,
    spp.slug::text AS sprint_project_slug,
    spw.slug::text AS sprint_workspace_slug
FROM "activity_logs" al
JOIN "users" u ON al.user_id = u.id
LEFT JOIN "tasks" t ON (al.entity_type IN ('Task', 'Task Label', 'TaskAttachment', 'Task Attchment')) AND al.entity_id = t.id
LEFT JOIN "projects" tp ON t.project_id = tp.id
LEFT JOIN "workspaces" tw ON tp.workspace_id = tw.id
LEFT JOIN "task_comments" tc ON (al.entity_type IN ('Task Comment', 'TaskComment')) AND al.entity_id = tc.id
LEFT JOIN "tasks" ct ON tc.task_id = ct.id
LEFT JOIN "projects" ctp ON ct.project_id = ctp.id
LEFT JOIN "workspaces" ctw ON ctp.workspace_id = ctw.id
LEFT JOIN "projects" pp ON al.entity_type = 'Project' AND al.entity_id = pp.id
LEFT JOIN "workspaces" pw ON pp.workspace_id = pw.id
LEFT JOIN "workspaces" ws ON al.entity_type = 'Workspace' AND al.entity_id = ws.id
LEFT JOIN "sprints" sp ON al.entity_type = 'Sprint' AND al.entity_id = sp.id
LEFT JOIN "projects" spp ON sp.project_id = spp.id
LEFT JOIN "workspaces" spw ON spp.workspace_id = spw.id
WHERE
    (al.entity_type = 'Workspace' AND al.entity_id = $1::uuid)
    OR (al.entity_type = 'Project' AND al.entity_id IN (
        SELECT p.id FROM "projects" p WHERE p.workspace_id = $1::uuid
    ))
    OR (al.entity_type IN ('Task', 'Task Label', 'TaskAttachment', 'Task Attchment') AND al.entity_id IN (
        SELECT t2.id FROM "tasks" t2
        JOIN "projects" p2 ON t2.project_id = p2.id
        WHERE p2.workspace_id = $1::uuid
    ))
    OR (al.entity_type IN ('Task Comment', 'TaskComment') AND al.entity_id IN (
        SELECT tc2.id FROM "task_comments" tc2
        JOIN "tasks" t3 ON tc2.task_id = t3.id
        JOIN "projects" p3 ON t3.project_id = p3.id
        WHERE p3.workspace_id = $1::uuid
    ))
    OR (al.entity_type = 'Sprint' AND (
        al.entity_id IN (
            SELECT s2.id FROM "sprints" s2
            JOIN "projects" p4 ON s2.project_id = p4.id
            WHERE p4.workspace_id = $1::uuid
        )
        OR (al.new_value->>'projectId' IN (
            SELECT p5.id::text FROM "projects" p5 WHERE p5.workspace_id = $1::uuid
        ))
        OR (al.old_value->>'projectId' IN (
            SELECT p6.id::text FROM "projects" p6 WHERE p6.workspace_id = $1::uuid
        ))
    ))
ORDER BY al.created_at DESC
LIMIT $3::integer
OFFSET $2::integer
`

type ListWorkspaceActivityOptimizedParams struct {
	WorkspaceID uuid.UUID `json:"workspace_id"`
	OffsetVal   int32     `json:"offset_val"`
	LimitVal    int32     `json:"limit_val"`
}

type ListWorkspaceActivityOptimizedRow struct {
	ID                   uuid.UUID        `json:"id"`
	Type                 ActivityType     `json:"type"`
	Description          string           `json:"description"`
	EntityType           string           `json:"entity_type"`
	EntityID             uuid.UUID        `json:"entity_id"`
	CreatedAt            pgtype.Timestamp `json:"created_at"`
	UserID               uuid.UUID        `json:"user_id"`
	FirstName            string           `json:"first_name"`
	LastName             string           `json:"last_name"`
	Email                string           `json:"email"`
	Avatar               pgtype.Text      `json:"avatar"`
	TaskSlug             string           `json:"task_slug"`
	TaskProjectSlug      string           `json:"task_project_slug"`
	TaskWorkspaceSlug    string           `json:"task_workspace_slug"`
	ProjectSlug          string           `json:"project_slug"`
	ProjectWorkspaceSlug string           `json:"project_workspace_slug"`
	WorkspaceSlug        string           `json:"workspace_slug"`
	SprintSlug           string           `json:"sprint_slug"`
	SprintProjectSlug    string           `json:"sprint_project_slug"`
	SprintWorkspaceSlug  string           `json:"sprint_workspace_slug"`
}

func (q *Queries) ListWorkspaceActivityOptimized(ctx context.Context, arg ListWorkspaceActivityOptimizedParams) ([]ListWorkspaceActivityOptimizedRow, error) {
	rows, err := q.db.Query(ctx, listWorkspaceActivityOptimized, arg.WorkspaceID, arg.OffsetVal, arg.LimitVal)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListWorkspaceActivityOptimizedRow{}
	for rows.Next() {
		var i ListWorkspaceActivityOptimizedRow
		if err := rows.Scan(
			&i.ID,
			&i.Type,
			&i.Description,
			&i.EntityType,
			&i.EntityID,
			&i.CreatedAt,
			&i.UserID,
			&i.FirstName,
			&i.LastName,
			&i.Email,
			&i.Avatar,
			&i.TaskSlug,
			&i.TaskProjectSlug,
			&i.TaskWorkspaceSlug,
			&i.ProjectSlug,
			&i.ProjectWorkspaceSlug,
			&i.WorkspaceSlug,
			&i.SprintSlug,
			&i.SprintProjectSlug,
			&i.SprintWorkspaceSlug,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const resolveActivityProjectByIDOrSlug = `-- name: ResolveActivityProjectByIDOrSlug :one
SELECT p.id, p.slug, w.slug AS workspace_slug
FROM "projects" p
LEFT JOIN "workspaces" w ON p.workspace_id = w.id
WHERE ($1::boolean = true AND p.id = $2::uuid)
   OR ($1::boolean = false AND p.slug = $3::text)
LIMIT 1
`

type ResolveActivityProjectByIDOrSlugParams struct {
	IsUuid   bool        `json:"is_uuid"`
	ProjUuid pgtype.UUID `json:"proj_uuid"`
	ProjSlug string      `json:"proj_slug"`
}

type ResolveActivityProjectByIDOrSlugRow struct {
	ID            uuid.UUID   `json:"id"`
	Slug          string      `json:"slug"`
	WorkspaceSlug pgtype.Text `json:"workspace_slug"`
}

func (q *Queries) ResolveActivityProjectByIDOrSlug(ctx context.Context, arg ResolveActivityProjectByIDOrSlugParams) (ResolveActivityProjectByIDOrSlugRow, error) {
	row := q.db.QueryRow(ctx, resolveActivityProjectByIDOrSlug, arg.IsUuid, arg.ProjUuid, arg.ProjSlug)
	var i ResolveActivityProjectByIDOrSlugRow
	err := row.Scan(&i.ID, &i.Slug, &i.WorkspaceSlug)
	return i, err
}

